def compress_ranges(nums: list[int]) -> str:
    """
    Compress a sorted list of strictly increasing integers into a compact string
    representation. Consecutive runs of length >= 3 are represented as 'a..b',
    otherwise each number is written individually. Items are joined by commas
    with no spaces. An empty list returns an empty string.
    """
    if not nums:
        return ""

    parts: list[str] = []
    start = nums[0]
    prev = nums[0]

    for n in nums[1:]:
        if n == prev + 1:
            # still in a run
            prev = n
            continue
        # run ended at prev
        if prev - start + 1 >= 3:
            parts.append(f"{start}..{prev}")
        else:
            parts.extend(str(x) for x in range(start, prev + 1))
        start = prev = n

    # handle the final run
    if prev - start + 1 >= 3:
        parts.append(f"{start}..{prev}")
    else:
        parts.extend(str(x) for x in range(start, prev + 1))

    return ",".join(parts)

