from collections import deque

def knight_min_moves(n: int, start: list[int], end: list[int], blocked: list[list[int]]) -> int:
    if start == end:
        return 0

    blocked_set = set(tuple(b) for b in blocked)

    if tuple(end) in blocked_set:
        return -1

    # Knight moves
    moves = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]

    # BFS
    visited = set()
    visited.add(tuple(start))

    queue = deque()
    queue.append((start[0], start[1], 0))

    while queue:
        r, c, dist = queue.popleft()

        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                pos = (nr, nc)
                if pos not in visited and pos not in blocked_set:
                    if pos == tuple(end):
                        return dist + 1
                    visited.add(pos)
                    queue.append((nr, nc, dist + 1))

    return -1

