    """
    Return the minimum number of knight moves from start to end on an n x n board,
    avoiding cells listed in blocked. Return 0 if start == end, or -1 if the
    destination is unreachable (including if end is blocked).
    """
    # Quick checks
    if start == end:
        return 0

    blocked_set: Set[Tuple[int, int]] = {(r, c) for r, c in blocked}
    if tuple(end) in blocked_set:
        return -1

    # Knight move offsets
    moves = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]

    visited: Set[Tuple[int, int]] = set()
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited.add((start[0], start[1]))

    while queue:
        r, c, dist = queue.popleft()

        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if (nr, nc) == tuple(end):
                    return dist + 1
                if (nr, nc) not in visited and (nr, nc) not in blocked_set:
                    visited.add((nr, nc))
                    queue.append((nr, nc, dist + 1))

    return -1

